		assertEquals(LmdbCompatibilityFixtures.PRODUCER_CLASS, provenance.getProperty("producer.class.sha256"));
		assertEquals(LmdbCompatibilityFixtures.PRODUCER_JAR, provenance.getProperty("producer.jar.sha256"));
