	@ParameterizedTest
	@ValueSource(strings = { "v6-inline-ordered.zip", "v6-inline-legacy-numeric.zip",
			"v6-dictionary-ordered.zip", "v6-dictionary-legacy-numeric.zip", "v6-fresh-aliases.zip" })
	void exactTermsSurviveReadWriteGcAndReopen(String fixture) throws Exception {
		extract(fixture, directory);
		Properties provenance = properties(directory, "producer.properties");
		Properties format = properties(directory, "store.properties");
		boolean inline = Boolean.parseBoolean(format.getProperty("inline-literals"));
		SailRepository repository = repository(directory, inline);
		repository.init();
		try {
			ValueStore values = (ValueStore) repository.getValueFactory();
			try (var connection = repository.getConnection()) {
				assertSeedIdentity(connection, values, provenance);
				assertEquals(Long.parseLong(provenance.getProperty("statements.explicit")), count(connection, false));
				assertEquals(Long.parseLong(provenance.getProperty("statements.all")), count(connection, true));
				assertEquals("urn:v6:", connection.getNamespace("v6"));
				assertTrue(connection.hasStatement(VF.createBNode("shared-across-graphs"), null, null, false,
						VF.createIRI("urn:v6:graph")));
				assertTrue(connection.hasStatement(VF.createBNode("shared-across-graphs"), null, null, true,
						VF.createIRI("urn:v6:inferred-graph")));
				assertTrue(termIds(values).contains(Long.parseLong(provenance.getProperty("standalone.id"))));
				// One nested owner is removed; the inner term and its exact date remain referenced elsewhere.
				connection.begin();
				connection.remove(VF.createIRI("urn:v6:nested"), null, null);
				connection.commit();
				assertTrue(connection.hasStatement(VF.createIRI("urn:v6:shared"), null, null, false));
				Value inner = VF.createTripleTerm(VF.createIRI("urn:v6:inner"), VF.createIRI("urn:v6:literal"),
						VF.createLiteral("2026-10-03T12:00:01.0Z", CoreDatatype.XSD.DATETIME));
				assertNotEquals(LmdbValue.UNKNOWN_ID, values.getId(inner));
				connection.begin();
				connection.add(VF.createIRI("urn:v6:nested"), VF.createIRI("urn:v6:literal"),
						VF.createTripleTerm(VF.createIRI("urn:v6:outer"), VF.createIRI("urn:v6:literal"), inner));
				connection.commit();
				connection.begin();
				connection.remove(VF.createIRI("urn:v6:subject:0"), null, null);
				connection.rollback();
				assertSeedIdentity(connection, values, provenance);
				maintenanceWrite(connection);
			}
		} finally {
			repository.shutDown();
		}
		repository = repository(directory, inline);
		repository.init();
		try (var connection = repository.getConnection()) {
			assertSeedIdentity(connection, (ValueStore) repository.getValueFactory(), provenance);
			assertTrue(connection.hasStatement(VF.createIRI("urn:v6:maintenance"), null, null, false));
		} finally {
			repository.shutDown();
		}
		assertEquals(format, properties(directory, "store.properties"));
		assertArrayEquals(new byte[] { 6 }, nativeGet(directory, "gc_meta", new byte[] { 3 }));
	}

	@Test
	void actualFreshProducerUsesOverlappingFamilyOrdinalsWithoutCrossFamilyReuse() throws Exception {
		extract("v6-fresh-aliases.zip", directory);
		Properties provenance = properties(directory, "producer.properties");
		long bnodeId = Long.parseLong(provenance.getProperty("family.id.bnode"));
		long literalId = Long.parseLong(provenance.getProperty("family.id.literal"));
		long tripleId = Long.parseLong(provenance.getProperty("family.id.triple"));
		assertEquals(ValueIds.referenceOrdinal(bnodeId), ValueIds.referenceOrdinal(literalId));
		assertEquals(ValueIds.referenceOrdinal(bnodeId), ValueIds.referenceOrdinal(tripleId));
		assertNotEquals(ValueIds.getIdType(bnodeId), ValueIds.getIdType(literalId));
		nativePut(directory, "free_ids", LmdbCompatibilityFixtures.idKey(bnodeId), new byte[0]);
		var repository = repository(directory, true);
		repository.init();
		try (var connection = repository.getConnection()) {
			var values = (ValueStore) repository.getValueFactory();
			assertSeedIdentity(connection, values, provenance);
			connection.begin();
			var fresh = VF.createLiteral("fresh family-safe reference " + "q".repeat(1024));
			connection.add(VF.createIRI("urn:v6:family-safe"), VF.createIRI("urn:v6:literal"), fresh);
			connection.commit();
			assertEquals(bnodeId, values.getId(VF.createBNode("shared-across-graphs")));
			assertSeedIdentity(connection, values, provenance);
		} finally {
			repository.shutDown();
		}
	}

