	@Test
	void staleUnusedAndFreeHintsCannotRecycleLiveCoreOwners() throws Exception {
		extract("v6-dictionary-ordered.zip", directory);
		Properties provenance = properties(directory, "producer.properties");
		long id = Long.parseLong(provenance.getProperty("core.0.id"));
		byte[] idKey = LmdbCompatibilityFixtures.idKey(id);
		byte[] revision = LmdbCompatibilityFixtures.unsigned(1);
		byte[] unused = new byte[revision.length + idKey.length];
		System.arraycopy(revision, 0, unused, 0, revision.length);
		System.arraycopy(idKey, 0, unused, revision.length, idKey.length);
		nativePut(directory, "unused_ids", unused, new byte[0]);
		nativePut(directory, "free_ids", idKey, new byte[0]);
		nativePut(directory, null, new byte[] { 8 }, null);
		SailRepository repository = repository(directory, false);
		repository.init();
		try (var connection = repository.getConnection()) {
			ValueStore values = (ValueStore) repository.getValueFactory();
			assertSeedIdentity(connection, values, provenance);
			long standalone = Long.parseLong(provenance.getProperty("standalone.id"));
			var fresh = VF.createTripleTerm(VF.createIRI("urn:v6:allocated-subject"), VF.createIRI("urn:v6:literal"),
					VF.createLiteral("new core reference " + "y".repeat(1024)));
			connection.begin();
			connection.add(VF.createIRI("urn:v6:allocated"), VF.createIRI("urn:v6:literal"), fresh);
			connection.commit();
			assertTrue(ValueIds.referenceOrdinal(values.getId(fresh)) > ValueIds.referenceOrdinal(standalone));
			assertEquals(id, values.getId(expectedLiteral(provenance, "core.0")));
		} finally {
			repository.shutDown();
		}
	}

