	@ParameterizedTest
	@ValueSource(strings = { "outer", "native", "schema", "refcounts", "values", "triples", "bulk" })
	void inconsistentGenerationRejectsWithoutWrites(String damage) throws Exception {
		extract("v6-inline-ordered.zip", directory);
		switch (damage) {
		case "outer":
			Files.writeString(directory.resolve("lmdbrdf.ver"), "unsupported marker");
			break;
		case "native":
			nativePut(directory, "gc_meta", new byte[] { 3 }, null);
			break;
		case "schema":
			nativePut(directory, "gc_meta", new byte[] { 2 }, new byte[] { 99 });
			break;
		case "refcounts":
			nativePut(directory, "ref_counts", new byte[] { 0 }, new byte[] { 99 });
			break;
		case "values":
			Files.move(directory.resolve("values/data.mdb"), directory.resolve("saved-values.mdb"));
			break;
		case "triples":
			Files.move(directory.resolve("triples/data.mdb"), directory.resolve("saved-triples.mdb"));
			break;
		case "bulk":
			Files.writeString(directory.resolve(".lmdb-bulk-load.incomplete"), "incomplete");
			break;
		default:
			throw new AssertionError(damage);
		}
		rejectWithoutMutation(true);
	}

	@Test
	void unknownPropertiesSurviveIndexChanges() throws Exception {
		extract("v6-inline-ordered.zip", directory);
		Properties format = properties(directory, "store.properties");
		format.setProperty("future.custom-key", "kept");
		save(directory, format);
		var config = config(true);
		config.setTripleIndexes("spoc,posc");
		SailRepository repository = new SailRepository(new LmdbStore(directory.toFile(), config));
		repository.init();
		try (var connection = repository.getConnection()) {
			assertSeedIdentity(connection,
					(ValueStore) repository.getValueFactory(), properties(directory, "producer.properties"));
		} finally {
			repository.shutDown();
		}
		Properties after = properties(directory, "store.properties");
		assertEquals("kept", after.getProperty("future.custom-key"));
		for (String key : format.stringPropertyNames()) {
			if (!key.equals("triple-indexes")) {
				assertEquals(format.getProperty(key), after.getProperty(key), key);
			}
		}
	}

	private void rejectWithoutMutation(boolean inline) throws Exception {
		var before = snapshot(directory);
		SailRepository repository = repository(directory, inline);
		try {
			assertThrows(RuntimeException.class, repository::init);
		} finally {
			repository.shutDown();
		}
		assertEquals(before, snapshot(directory));
	}

	static LmdbStoreConfig config(boolean inline) {
		return new LmdbStoreConfig("spoc,posc,ospc").setInlineLiterals(inline)
				.setForceSync(true)
				.setSketchEstimatorEnabled(false)
				.setValueHashCacheEnabled(false);
	}

	static SailRepository repository(Path directory, boolean inline) {
		return new SailRepository(new LmdbStore(directory.toFile(), config(inline)));
	}

	static void maintenanceWrite(RepositoryConnection connection) {
		connection.begin();
		connection.add(VF.createIRI("urn:v6:maintenance"), VF.createIRI("urn:v6:literal"),
				VF.createLiteral("maintenance write"), VF.createIRI("urn:v6:graph"));
		connection.commit();
	}

	static void assertSeedIdentity(RepositoryConnection connection, ValueStore values, Properties provenance)
			throws Exception {
		for (String group : new String[] { "literal", "core" }) {
			int count = Integer.parseInt(provenance.getProperty(group + ".count"));
			Set<Literal> expected = new HashSet<>();
			Set<Literal> actual = new HashSet<>();
			for (int i = 0; i < count; i++) {
				String prefix = group + "." + i;
				Literal literal = expectedLiteral(provenance, prefix);
				expected.add(literal);
				Resource subject = VF.createIRI(group.equals("literal") ? "urn:v6:subject:" + i
						: provenance.getProperty(prefix + ".subject"));
				try (var rows = connection.getStatements(subject, VF.createIRI("urn:v6:literal"), null, false)) {
					assertTrue(rows.hasNext(), prefix);
					Value object = rows.next().getObject();
					assertFalse(rows.hasNext(), prefix);
					Literal found = (Literal) object;
					assertEquals(literal.getLabel(), found.getLabel(), prefix);
					assertEquals(literal.getDatatype(), found.getDatatype(), prefix);
					assertEquals(literal.getLanguage(), found.getLanguage(), prefix);
					assertEquals(literal.getBaseDirection(), found.getBaseDirection(), prefix);
					actual.add(found);
				}
				assertTrue(connection.hasStatement(subject, VF.createIRI("urn:v6:literal"), literal, false), prefix);
				assertEquals(Long.parseLong(provenance.getProperty(prefix + ".id")), values.getId(literal), prefix);
			}
			assertEquals(count, expected.size(), "Fixture term identities are distinct");
			assertEquals(expected, actual);
			assertEquals(count, actual.size(), "No terms may collapse during enumeration");
		}
	}

	static Literal expectedLiteral(Properties provenance, String prefix) {
		String label = provenance.getProperty(prefix + ".label");
		String language = provenance.getProperty(prefix + ".language");
		String direction = provenance.getProperty(prefix + ".direction");
		if (!language.isEmpty()) {
			return direction.equals("NONE") || direction.isEmpty() ? VF.createLiteral(label, language)
					: VF.createLiteral(label, language, Literal.BaseDirection.valueOf(direction));
		}
		return VF.createLiteral(label, VF.createIRI(provenance.getProperty(prefix + ".datatype")));
	}

	static long count(RepositoryConnection connection, boolean inferred) {
		long count = 0;
		try (var rows = connection.getStatements(null, null, null, inferred)) {
			while (rows.hasNext()) {
				rows.next();
				count++;
			}
		}
		return count;
	}

	static Set<Long> termIds(ValueStore values) throws Exception {
		Set<Long> terms = new HashSet<>();
		try (var rows = values.getTripleTerms(-1, -1, -1)) {
			for (long[] row = rows.next(); row != null; row = rows.next()) {
				terms.add(row[3]);
			}
		}
		return terms;
	}
